Note that we wrap the function pointer with TORCH_BOX() - this is required for
stable ABI functions to handle argument boxing/unboxing correctly.
TORCH_BOX()
STABLE_TORCH_LIBRARY_IMPL ( extension_cpp , CPU , m ) { m . impl ( "mymuladd" , TORCH_BOX ( & mymuladd_cpu )); }
TORCH_LIBRARY_IMPL ( extension_cpp , CPU , m ) { m . impl ( "mymuladd" , & mymuladd_cpu ); }
